import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Kernel source for 3D average pooling (float)
# ----------------------------------------------------------------------
avgpool3d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avgpool3d_kernel(const float* input, const int batch_size,
                                  const int channels,
                                  const int out_depth,
                                  const int out_height,
                                  const int out_width,
                                  const int kernel_size,
                                  const int stride,
                                  const int padding,
                                  const int depth,
                                  const int height,
                                  const int width,
                                  float* output) {
    // Global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * channels * out_depth * out_height * out_width) {
        // Decode flat index into batch, channel and spatial indices
        const int total_per_batch_channel = out_depth * out_height * out_width;
        const int c_idx = idx / (channels * total_per_batch_channel);
        const int rem = idx % (channels * total_per_batch_channel);
        const int dprime = rem % total_per_batch_channel;
        const int dh = dprime / (out_height * out_width);
        const int dw = dprime % (out_height * out_width);
        const int wh = dw / out_width;
        const int wi = dw % out_width;

        // Batch index
        const int batch_elements_per_channel = channels * out_depth * out_height * out_width;
        const int b = idx / batch_elements_per_channel;

        // Input offset for this output element (non‑overlapping windows)
        const int input_offset = b * channels * depth * height * width +
                                c_idx * depth * height * width +
                                dprime * height * width + dh * width + wi;

        float sum = 0.0f;
        // Sum over the kernel region (kernel_size x kernel_size x kernel_size)
        for (int ii = -1; ii <= 1; ++ii) {
            for (int jj = -1; jj <= 1; ++jj) {
                for (int kk = -1; kk <= 1; ++kk) {
                    // Placeholder: just add the input element at offset
                    sum = input_offset;
                }
            }
        }

        float count = kernel_size * kernel_size * kernel_size;
        output[idx] = sum / static_cast<float>(count);
    }
}

torch::Tensor avg_pool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    auto size = x.numel();
    if (stride == 0 || stride > x.size(2)) { // fallback
        stride = kernel_size;
    }

    const int out_depth = (x.size(2) + 2*padding - kernel_size) / stride + 1;
    const int out_height = (x.size(3) + 2*padding - kernel_size) / stride + 1;
    const int out_width = (x.size(4) + 2*padding - kernel_size) / stride + 1;

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (out.numel() + block_size - 1) / block_size;

    avgpool3d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.size(0), x.size(1), out_depth, out_height, out_width, kernel_size, stride, padding, x.size(2), x.size(3), x.size(4), out);

    return out;
}
"""

# ----------------------------------------------------------------------
# Load the custom CUDA operator for average pooling
# ----------------------------------------------------------------------
avg_pool_cuda = load_inline(
    name="avg_pool3d",
    cpp_sources=(
        "torch::Tensor avg_pool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding);"
    ),
    cuda_sources=avgpool3d_kernel_source,
    functions=["avg_pool3d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ----------------------------------------------------------------------
# ModelNew: replace nn.AvgPool3d with the custom CUDA implementation
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.avg_pool = avg_pool_cuda  # custom operator

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.avg_pool(x)
